input.command:
S=/tmp/claude-0/-home-user-guidebook/a9452ae4-7ff6-5ee7-9d22-5a8cc7e0001d/scratchpad && mkdir -p $S/out && run(){ tree=$1; tag=$2; cd $S/$tree; 
 PYTHONDONTWRITEBYTECODE=1 python3 scripts/audit/schema_reference_audit.py > $S/out/sra-$tag.txt 2>&1; echo "sra $tag rc=$?";
 PYTHONDONTWRITEBYTECODE=1 python3 scripts/audit/joined_cells_census.py > $S/out/jcc-$tag.txt 2>&1; echo "jcc $tag rc=$?";
 PYTHONDONTWRITEBYTECODE=1 python3 workplan/pipeline-state-graph/build_graph.py --check > $S/out/bg-$tag.txt 2>&1; echo "bg $tag rc=$?";
 PYTHONDONTWRITEBYTECODE=1 python3 scripts/generate/context_map.py --check > $S/out/cm-$tag.txt 2>&1; echo "cm $tag rc=$?";
 PYTHONDONTWRITEBYTECODE=1 python3 scripts/audit/migration_reproducibility.py --deep > $S/out/mr-$tag.txt 2>&1; echo "mr $tag rc=$?";
 for c in "scripts/audit/scan_debt.py" "scripts/audit/verified_scan_integrity.py" "scripts/validate_schema.py --cross-check" "scripts/audit/research_batch_dod.py --all" "scripts/audit/research_protocol_audit.py" "scripts/audit/metadata_integrity_audit.py"; do n=$(basename ${c%% *} .py); PYTHONDONTWRITEBYTECODE=1 python3 $c > $S/out/$n-$tag.txt 2>&1; echo "$n $tag rc=$?"; done; }
(run wt head > $S/out/rc-head.txt 2>&1) & (run prevtree prev > $S/out/rc-prev.txt 2>&1) & wait; paste $S/out/rc-head.txt $S/out/rc-prev.txt; for f in sra jcc bg mr cm; do for t in head prev; do echo "== $f-$t"; grep -E 'EXAMINED|failure|VERDICT|PASS|FAIL|candidate' $S/out/$f-$t.txt | tail -4 | cut -c1-250; done; done

